   303	static mrb_int
   304	utf8len(const char* p, const char* e)
   305	{
   306	  mrb_int len;
   307	  mrb_int i;
   308	
   309	  if ((unsigned char)*p < 0x80) return 1;
   310	  len = utf8len_codepage[(unsigned char)*p];
   311	  if (len == 1) return 1;
   312	  if (len > e - p) return 1;
   313	  for (i = 1; i < len; ++i)
   314	    if ((p[i] & 0xc0) != 0x80)
   315	      return 1;
   316	  return len;
   317	}
   318	
   319	mrb_int
   320	mrb_utf8_len(const char *str, mrb_int byte_len)
   321	{
   322	  mrb_int total = 0;
   323	  const char *p = str;
   324	  const char *e = p + byte_len;
   325	
   326	  while (p < e) {
   327	    p += utf8len(p, e);
   328	    total++;
   329	  }
   330	  return total;
   331	}
