   338	
   339	  if (RSTR_ASCII_P(s)) {
   340	    return byte_len;
   341	  }
   342	  else {
   343	    mrb_int utf8_len = mrb_utf8_len(RSTR_PTR(s), byte_len);
   344	    if (byte_len == utf8_len) RSTR_SET_ASCII_FLAG(s);
   345	    return utf8_len;
   346	  }
