   351	/* map character index to byte offset index */
   352	static mrb_int
   353	chars2bytes(mrb_value s, mrb_int off, mrb_int idx)
   354	{
   355	  if (RSTR_ASCII_P(mrb_str_ptr(s))) {
   356	    return idx;
   357	  }
   358	  else {
   359	    mrb_int i, b, n;
   360	    const char *p = RSTRING_PTR(s) + off;
   361	    const char *e = RSTRING_END(s);
   362	
   363	    for (b=i=0; p<e && i<idx; i++) {
   364	      n = utf8len(p, e);
   365	      b += n;
   366	      p += n;
   367	    }
   368	    return b;
   369	  }
   370	}
