   372	/* map byte offset to character index */
   373	static mrb_int
   374	bytes2chars(char *p, mrb_int len, mrb_int bi)
   375	{
   376	  const char *e = p + (size_t)len;
   377	  const char *pivot = p + bi;
   378	  mrb_int i;
   379	
   380	  for (i = 0; p < pivot; i ++) {
   381	    p += utf8len(p, e);
   382	  }
   383	  if (p != pivot) return -1;
   384	  return i;
   385	}
