   387	static const char *
   388	char_adjust(const char *beg, const char *end, const char *ptr)
   389	{
   390	  if ((ptr > beg || ptr < end) && (*ptr & 0xc0) == 0x80) {
   391	    const int utf8_adjust_max = 3;
   392	    const char *p;
   393	
   394	    if (ptr - beg > utf8_adjust_max) {
   395	      beg = ptr - utf8_adjust_max;
   396	    }
   397	
   398	    p = ptr;
   399	    while (p > beg) {
   400	      p --;
   401	      if ((*p & 0xc0) != 0x80) {
   402	        int clen = utf8len(p, end);
   403	        if (clen > ptr - p) return p;
   404	        break;
   405	      }
   406	    }
   407	  }
   408	
   409	  return ptr;
   410	}
   411	
   412	static const char *
   413	char_backtrack(const char *ptr, const char *end)
   414	{
   415	  if (ptr < end) {
   416	    const int utf8_bytelen_max = 4;
   417	    const char *p;
   418	
   419	    if (end - ptr > utf8_bytelen_max) {
   420	      ptr = end - utf8_bytelen_max;
   421	    }
   422	
   423	    p = end;
   424	    while (p > ptr) {
   425	      p --;
   426	      if ((*p & 0xc0) != 0x80) {
   427	        int clen = utf8len_codepage[(unsigned char)*p];
   428	        if (clen == end - p) { return p; }
   429	        break;
   430	      }
   431	    }
   432	  }
   433	
   434	  return end - 1;
   435	}
