   476	static mrb_int
   477	str_index_str_by_char(mrb_state *mrb, mrb_value str, mrb_value sub, mrb_int pos)
   478	{
   479	  const char *p = RSTRING_PTR(str);
   480	  const char *pend = p + RSTRING_LEN(str);
   481	  const char *s = RSTRING_PTR(sub);
   482	  const mrb_int slen = RSTRING_LEN(sub);
   483	  mrb_int off = pos;
   484	
   485	  for (; pos > 0; pos --) {
   486	    if (pend - p < 1) { return -1; }
   487	    p += utf8len(p, pend);
   488	  }
   489	
   490	  if (slen < 1) { return off; }
   491	
   492	  return str_index_str_by_char_search(mrb, p, pend, s, slen, off);
   493	}
