   506	static inline mrb_int
   507	mrb_memsearch_qs(const unsigned char *xs, mrb_int m, const unsigned char *ys, mrb_int n)
   508	{
   509	  const unsigned char *x = xs, *xe = xs + m;
   510	  const unsigned char *y = ys;
   511	  int i;
   512	  ptrdiff_t qstable[256];
   513	
   514	  /* Preprocessing */
   515	  for (i = 0; i < 256; ++i)
   516	    qstable[i] = m + 1;
   517	  for (; x < xe; ++x)
   518	    qstable[*x] = xe - x;
   519	  /* Searching */
   520	  for (; y + m <= ys + n; y += *(qstable + y[m])) {
   521	    if (*xs == *y && memcmp(xs, y, m) == 0)
   522	      return (mrb_int)(y - ys);
   523	  }
   524	  return -1;
   525	}
   526	
   527	static mrb_int
   528	mrb_memsearch(const void *x0, mrb_int m, const void *y0, mrb_int n)
   529	{
   530	  const unsigned char *x = (const unsigned char *)x0, *y = (const unsigned char *)y0;
   531	
   532	  if (m > n) return -1;
   533	  else if (m == n) {
   534	    return memcmp(x0, y0, m) == 0 ? 0 : -1;
   535	  }
   536	  else if (m < 1) {
   537	    return 0;
   538	  }
   539	  else if (m == 1) {
   540	    const unsigned char *ys = (const unsigned char *)memchr(y, *x, n);
   541	
   542	    if (ys)
   543	      return (mrb_int)(ys - y);
   544	    else
   545	      return -1;
   546	  }
   547	  return mrb_memsearch_qs((const unsigned char *)x0, m, (const unsigned char *)y0, n);
   548	}
