   550	static void
   551	str_share(mrb_state *mrb, struct RString *orig, struct RString *s)
   552	{
   553	  size_t len = (size_t)orig->as.heap.len;
   554	
   555	  mrb_assert(!RSTR_EMBED_P(orig));
   556	  if (RSTR_NOFREE_P(orig)) {
   557	    str_init_nofree(s, orig->as.heap.ptr, len);
   558	  }
   559	  else if (RSTR_SHARED_P(orig)) {
   560	    str_init_shared(mrb, orig, s, orig->as.heap.aux.shared);
   561	  }
   562	  else if (RSTR_FSHARED_P(orig)) {
   563	    str_init_fshared(orig, s, orig->as.heap.aux.fshared);
   564	  }
   565	  else if (mrb_frozen_p(orig) && !RSTR_POOL_P(orig)) {
   566	    str_init_fshared(orig, s, orig);
   567	  }
   568	  else {
   569	    if (orig->as.heap.aux.capa > orig->as.heap.len) {
   570	      orig->as.heap.ptr = (char *)mrb_realloc(mrb, orig->as.heap.ptr, len+1);
   571	      orig->as.heap.aux.capa = (mrb_ssize)len;
   572	    }
   573	    str_init_shared(mrb, orig, s, NULL);
   574	    str_init_shared(mrb, orig, orig, s->as.heap.aux.shared);
   575	  }
   576	}
